#!/usr/bin/env python3
"""Approved expanded subtitle preview polish; synchronize both build modes."""
import base64
import hashlib
import runpy
from pathlib import Path
root = Path(__file__).resolve().parents[2]
canonical = root / "Gallery-current.html"
raw = canonical.read_bytes()
assert len(raw) == 6916210 and hashlib.sha256(raw).hexdigest() == "72345931b0931aa0f9799c3fdf0355a1347b2e4c3ec79a1a403dbfe3ebc63dda"
builder = runpy.run_path(str(root / "tools/build-gallery.py"))
builder["check"]()
source = raw.decode("utf-8")
pairs = [
    (".overlay .dialog.subtitle-preview-dialog{\n  width:min(1360px,calc(100vw - 30px));max-height:min(94dvh,940px);\n}\n.subtitle-preview-dialog .dialog-scroll{padding:16px 20px 18px 25px}\n.subtitle-preview-dialog .dialog-head{margin-bottom:9px}\n.subtitle-expanded-note{font-size:12px;color:var(--muted);line-height:1.5;margin:0 0 13px}", ".overlay .dialog.subtitle-preview-dialog{\n  width:min(1360px,calc(100vw - 30px));max-height:min(94dvh,940px);padding:0;\n}\n.subtitle-preview-dialog .dialog-scroll{margin:0;padding:12px}\n.subtitle-preview-dialog .dialog-head{display:grid;grid-template-columns:minmax(0,1fr) auto auto;align-items:center;gap:10px;margin-bottom:10px}\n.subtitle-preview-dialog .dialog-head h2{margin:0;min-width:0;overflow-wrap:anywhere}\n.subtitle-preview-dialog .dialog-head #close-dialog{justify-self:end}\n.subtitle-expanded-header-controls{display:flex;align-items:center;justify-content:flex-end;gap:8px;min-width:0}\n.subtitle-expanded-header-controls #subtitle-actual-size{min-width:58px;min-height:32px;white-space:nowrap}\n.subtitle-expanded-header-controls #subtitle-actual-size[aria-pressed=\"true\"]{border-color:var(--accent);background:var(--strong)}"),
    ("width:min(1280px,100%,calc((100dvh - 205px)*16/9));", "width:min(1280px,100%,calc((min(94dvh,940px) - 88px)*16/9));"),
    (".subtitle-expanded-toolbar{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap;margin-top:13px}\n.subtitle-expanded-toolbar .btn[aria-pressed=\"true\"]{border-color:var(--accent);background:var(--strong)}\n.subtitle-expanded-help{color:var(--muted);font-size:11px;line-height:1.45;margin:0;flex:1}\n@media(max-width:580px){\n \n \n .subtitle-preview-dialog .dialog-scroll{padding:12px 13px 14px 18px}\n .subtitle-expanded-toolbar{align-items:flex-start;flex-direction:column}\n}", "@media(max-width:580px){\n .subtitle-preview-dialog .dialog-head{grid-template-columns:minmax(0,1fr) auto;gap:8px}\n .subtitle-preview-dialog .dialog-head h2{font-size:18px}\n .subtitle-preview-dialog .dialog-head #close-dialog{grid-column:2;grid-row:1}\n .subtitle-expanded-header-controls{grid-column:1/-1;grid-row:2;justify-content:flex-end}\n .subtitle-expanded-viewport:not(.is-actual-size) .subtitle-stage{width:min(1280px,100%,calc((min(94dvh,940px) - 124px)*16/9))}\n}"),
    ("min-height:32px;min-width:112px;padding:3px;border:1px solid var(--line);border-radius:10px;background:var(--surface);color:var(--muted);font-size:11px;font-weight:660}", "min-height:32px;min-width:148px;padding:3px;border:1px solid var(--line);border-radius:10px;background:var(--surface);color:var(--muted);font-size:11px;font-weight:660}"),
    (".subtitle-expanded-scene-heading{display:flex;justify-content:flex-end;margin:0 0 10px}", ".sf-subtitle-scene-toggle .scene-day,.sf-subtitle-scene-toggle .scene-night{display:flex;align-items:center;justify-content:center;gap:4px;white-space:nowrap}\n.sf-subtitle-scene-toggle .icon{flex:none}"),
    ("const SVG={refresh:", "const SVG={sun:'<circle cx=\"12\" cy=\"12\" r=\"4\"/><path d=\"M12 2v2m0 16v2M2 12h2m16 0h2M4.93 4.93l1.42 1.42m11.3 11.3l1.42 1.42m0-14.14-1.42 1.42M6.35 17.65l-1.42 1.42\"/>',moon:'<path d=\"M12 3a9 9 0 1 0 9 9 7 7 0 0 1 -9 -9z\"/>',refresh:"),
    ("<span class=\"scene-day\" aria-hidden=\"true\">Day</span><span class=\"scene-night\" aria-hidden=\"true\">Night</span>", "<span class=\"scene-day\" aria-hidden=\"true\">${icon('sun',14)}Day</span><span class=\"scene-night\" aria-hidden=\"true\">${icon('moon',14)}Night</span>"),
    ("<div class=\"sf-subtitle-heading\">", "<div class=\"sf-subtitle-heading\" id=\"settings-subtitle-appearance\" tabindex=\"-1\">"),
    ("   <div class=\"sf-subtitle-utilities\" id=\"settings-subtitle-appearance\" tabindex=\"0\" role=\"region\" aria-label=\"Subtitle settings utilities\"><details><summary>${icon('info',15)} About subtitle rendering</summary><p>Subtitle size scales with the displayed video area. These settings are saved locally and used in the preview. Applying custom styling in the playback engine is still planned; actual player rendering may differ.</p></details><span class=\"only-sr\" id=\"subtitle-saved-status\" role=\"status\" aria-live=\"polite\"></span></div>", "   <span class=\"only-sr\" id=\"subtitle-saved-status\" role=\"status\" aria-live=\"polite\"></span>"),
    (".sf-subtitle-utilities{display:flex;justify-content:flex-end;margin-top:12px}\n", ""),
    (".sf-subtitle-utilities details{max-width:420px;border:1px solid var(--line);border-radius:10px;background:#ffffff07;padding:8px 10px;font-size:11px;color:var(--muted)}\n", ""),
    (".sf-subtitle-utilities summary{cursor:pointer;list-style:none;font-weight:650}\n", ""),
    (".sf-subtitle-utilities summary::-webkit-details-marker{display:none}\n", ""),
    (".sf-subtitle-utilities p{line-height:1.6;margin:8px 0 1px}\n", ""),
    ("#playback-subtitles-pane .sf-subtitle-utilities{margin-top:12px}\n", ""),
    ("#playback-subtitles-pane .sf-subtitle-utilities details{font-size:11px}\n", ""),
    ("modal('Expanded subtitle preview',`<div class=\"subtitle-expanded-scene-heading\">${subtitleSceneToggle()}</div>", "modal('Expanded subtitle preview',`<div class=\"subtitle-expanded-header-controls\"><button type=\"button\" class=\"btn small\" id=\"subtitle-actual-size\" aria-pressed=\"false\" aria-label=\"View at 100%\" title=\"View at 100% (1280 × 720 CSS pixels; scroll to inspect)\">100%</button>${subtitleSceneToggle()}</div>"),
    ("  </div>\n  <div class=\"subtitle-expanded-toolbar\"><button type=\"button\" class=\"btn small\" id=\"subtitle-actual-size\" aria-pressed=\"false\">View at 100%</button><p class=\"subtitle-expanded-help\" id=\"subtitle-expanded-help\">Fit to window. 100% shows the original 1280 × 720 CSS-pixel preview (scroll to inspect on smaller screens).</p></div>`);", "  </div>`);"),
    (" dialog.classList.add('subtitle-preview-dialog');\n bindSubtitleSceneToggle(dialog);", " dialog.classList.add('subtitle-preview-dialog');\n const headerControls=dialog.querySelector('.subtitle-expanded-header-controls');\n dialog.querySelector('.dialog-head').insertBefore(headerControls,dialog.querySelector('#close-dialog'));\n bindSubtitleSceneToggle(dialog);"),
    ("  actual.textContent=enabled?'Fit to window':'View at 100%';", "  actual.textContent=enabled?'Fit':'100%';\n  actual.setAttribute('aria-label',enabled?'Fit to window':'View at 100%');\n  actual.title=enabled?'Fit the preview to the window':'View at 100% (1280 × 720 CSS pixels; scroll to inspect)';"),
    (" const actual=dialog.querySelector('#subtitle-actual-size');\n actual.addEventListener", " const actual=dialog.querySelector('#subtitle-actual-size');\n actual.focus({preventScroll:true});\n actual.addEventListener"),
]
for old,new in pairs:
    assert source.count(old) == 1, old[:100]
    source = source.replace(old,new,1)
assert "About subtitle rendering" not in source
assert "subtitle-expanded-toolbar" not in source
full = source.encode("utf-8")
template = full
for name, sha in (("day","0bd22bbc4f21a48b3ee2c451995814ab5fc0406745b653eecf5a0dc834bfe4ae"),("night","3f37dcb26d19f07cabe7283d7894635f712649bc7caab68610bb11541e0171e4")):
    asset = (root / "assets/subtitle-preview" / f"shrine-{name}.png").read_bytes()
    assert hashlib.sha256(asset).hexdigest() == sha
    url = b"data:image/png;base64," + base64.b64encode(asset)
    assert template.count(url) == 1
    template = template.replace(url, f"__GALLERY_SHRINE_{name.upper()}_DATA_URL__".encode(), 1)
canonical.write_bytes(full)
(root / "src/Gallery.template.html").write_bytes(template)
assert builder["build"]("full") == full == builder["build"]("subtitle-preview")
(root / "Gallery-development.html").write_bytes(builder["build"]("development"))
(root / "tests/test_asset_build_modes.py").write_text("#!/usr/bin/env python3\n\"\"\"Check manual day/night controls in full and lightweight Gallery previews.\"\"\"\nfrom pathlib import Path\nimport os\nfrom playwright.sync_api import sync_playwright\n\nroot = Path(__file__).resolve().parents[1]\n\ndef assert_scene(page, night):\n    expected = \"1\" if night else \"0\"\n    layers = page.evaluate(\"\"\"() => subtitleStages().map(s => ({\n        inline: s.querySelector('.subtitle-stage-night').style.opacity,\n        computed: getComputedStyle(s.querySelector('.subtitle-stage-night')).opacity\n    }))\"\"\")\n    assert layers and all(x == {\"inline\": expected, \"computed\": expected} for x in layers), layers\n    assert page.locator('.sf-subtitle-scene-toggle').evaluate_all(\n        \"(els) => els.every(e => e.getAttribute('aria-checked') === \" + repr(str(night).lower()) + \")\"\n    )\n\ndef open_subtitles(page, filename):\n    page.goto((root / filename).as_uri(), wait_until=\"load\")\n    page.wait_for_timeout(240)\n    page.locator(\"#settings\").click()\n    page.wait_for_function('() => document.body.classList.contains(\"settings-view\") && !galleryStageTransition && !gallerySettingsOpening')\n    page.wait_for_timeout(260)\n    page.locator('[data-settings-section=\"playback\"]').click()\n    page.wait_for_function(\"() => settingsLastSection === 'playback' && !document.querySelector('[data-settings-panel=playback]').hidden\")\n    page.locator('[data-playback-tab=\"subtitles\"]').click()\n\nwith sync_playwright() as pw:\n    browser = pw.chromium.launch(headless=True, executable_path=os.environ.get(\"GALLERY_TEST_CHROMIUM\") or None, args=[\"--no-sandbox\"])\n    geometries = {}\n    for filename, light in ((\"Gallery-current.html\", False), (\"Gallery-development.html\", True)):\n        for reduced in (\"no-preference\", \"reduce\"):\n            for width in (1600, 700, 420):\n                page = browser.new_page(viewport={\"width\": width, \"height\": 950}, reduced_motion=reduced)\n                errors = []\n                page.on(\"pageerror\", lambda e: errors.append(str(e)))\n                open_subtitles(page, filename)\n                main = page.locator(\"#subtitle-preview-stage\")\n                toggle = page.locator(\".sf-subtitle-preview-heading .sf-subtitle-scene-toggle\")\n                wide = width == 1600\n                assert toggle.is_visible() == wide\n                assert_scene(page, False)\n                assert page.locator(\"text=About subtitle rendering\").count() == 0\n                assert page.locator(\"#subtitle-saved-status\").count() == 1\n                assert page.locator(\"#settings-subtitle-appearance\").is_visible()\n                page.locator(\"#settings-subtitle-appearance\").focus()\n                assert page.locator(\"#settings-subtitle-appearance\").evaluate(\"(e) => document.activeElement === e\")\n                assert toggle.locator(\"svg\").count() == 2\n                if wide:\n                    assert page.locator(\".sf-subtitle-full-title\").inner_text() == \"Subtitle preview\"\n                    a,b = toggle.bounding_box(), main.bounding_box()\n                    assert abs(a[\"x\"]+a[\"width\"]-b[\"x\"]-b[\"width\"]) <= 2 and a[\"y\"]+a[\"height\"] <= b[\"y\"]\n                    toggle.click()\n                    assert_scene(page, True)\n                    page.locator(\"#subtitle-expand-preview\").click()\n                else:\n                    page.locator(\"#subtitle-compact-preview\").click()\n                expanded = page.locator(\"#subtitle-expanded-stage\")\n                expanded.wait_for()\n                dialog_toggle = page.locator(\".dialog-head .subtitle-expanded-header-controls .sf-subtitle-scene-toggle\")\n                scale = page.locator(\".dialog-head #subtitle-actual-size\")\n                assert dialog_toggle.locator(\"svg\").count() == 2\n                assert scale.inner_text() == \"100%\"\n                assert page.locator(\".subtitle-expanded-toolbar, .subtitle-expanded-help\").count() == 0\n                assert page.locator(\".subtitle-preview-dialog .dialog-scroll\").evaluate(\"(e) => ['Top','Right','Bottom','Left'].every(s => getComputedStyle(e)['padding'+s] === '12px')\")\n                page.wait_for_timeout(260)\n                header = page.locator(\".subtitle-preview-dialog .dialog-head\").bounding_box()\n                a,b,c = scale.bounding_box(),dialog_toggle.bounding_box(),page.locator(\"#close-dialog\").bounding_box()\n                assert a[\"x\"]+a[\"width\"] <= b[\"x\"]+1\n                assert a[\"y\"]+a[\"height\"] <= header[\"y\"]+header[\"height\"]+1\n                assert b[\"x\"]+b[\"width\"] <= header[\"x\"]+header[\"width\"]+1\n                if width > 580:\n                    assert b[\"x\"]+b[\"width\"] <= c[\"x\"]+1\n                scale.click()\n                assert scale.inner_text() == \"Fit\" and scale.get_attribute(\"aria-pressed\") == \"true\"\n                assert expanded.evaluate(\"(e) => e.offsetWidth\") == 1280\n                scale.click()\n                assert scale.inner_text() == \"100%\" and scale.get_attribute(\"aria-pressed\") == \"false\"\n                assert expanded.evaluate(\"(e) => e.offsetWidth\") <= 1280\n                assert page.locator(\"#subtitle-expanded-viewport\").evaluate(\"(e) => e.scrollLeft\") == 0\n                assert_scene(page, wide)\n                dialog_toggle.press(\"Space\")\n                assert_scene(page, not wide)\n                dialog_toggle.click()\n                assert_scene(page, wide)\n                page.emulate_media(reduced_motion=\"reduce\" if reduced == \"no-preference\" else \"no-preference\")\n                page.wait_for_timeout(5500)\n                assert_scene(page, wide)\n                geometry = []\n                for stage in (main, expanded):\n                    for name, color in ((\"day\", \"rgb(213, 219, 226)\"), (\"night\", \"rgb(9, 27, 44)\")):\n                        layer = stage.locator(\".subtitle-stage-\" + name)\n                        if light:\n                            assert layer.get_attribute(\"src\") is None\n                            assert layer.evaluate(\"(e) => getComputedStyle(e).backgroundColor\") == color\n                        else:\n                            layer.evaluate(\"(e) => e.decode()\")\n                            assert layer.get_attribute(\"src\").startswith(\"data:image/png;base64,\")\n                            assert layer.evaluate(\"(e) => e.naturalWidth\") > 0\n                    if stage.is_visible():\n                        rect = stage.bounding_box()\n                        assert rect and abs(rect[\"width\"] / rect[\"height\"] - 16 / 9) < .02\n                        geometry.append((rect[\"width\"], rect[\"height\"]))\n                key = (reduced, width)\n                if light:\n                    assert len(geometry) == len(geometries[key])\n                    assert all(abs(a-b) <= 1 for x,y in zip(geometry,geometries[key]) for a,b in zip(x,y))\n                else:\n                    geometries[key] = geometry\n                page.locator(\"#close-dialog\").click()\n                page.wait_for_selector(\"#subtitle-expanded-stage\", state=\"detached\")\n                assert_scene(page, wide)\n                page.locator(\"#subtitle-reset\").click()\n                assert page.locator(\"#subtitle-saved-status\").text_content() == \"Subtitle preview settings reset to defaults.\"\n                assert not errors, errors\n                page.close()\n                print(filename, reduced, width, \"passed\", flush=True)\n    browser.close()\nprint(\"Both modes: manual scene switching, synchronization, geometry, keyboard and reduced motion passed.\")\n", encoding="utf-8")
print("Expanded subtitle preview header, padding, icons and help removal applied; both builds synchronized.")
